# v1: v0 plus a fixed draft chain, bigger tribute bags, retreat when outnumbered or in danger,
# and altar choice that avoids monolith reach.

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat: low health always; mid health when carrying gems and under threat
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and in_danger() and health() < 0.5 * max_health())):
    recall()
    end_turn()

# outnumbered: step away from the nearest visible enemy instead of trading badly
if not at_spawn and enemies_within(4) > 0 and local_strength(4) < 0.6:
    let threat = unit_position( nearest( enemies_visible() ) )
    move_away_from(threat)
    end_turn()

let enemy = first( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

# carry gems to a tribute altar; bigger bags, delivered early when threatened
let deliver = gems() >= 8 or (gems() > 0 and in_danger())
if gems() > 0 and deliver:
    let open_altars = minus( altars(), locked_altars() )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # prefer altars outside monolith reach (monoliths kill carriers)
    let goal_altars = minus( open_altars, ring( monolith_tiles(), 5 ) )
    if count(goal_altars) > 0:
        move_towards( closest( ring(goal_altars, 1) ) )
    else:
        move_towards( closest( ring(open_altars, 1) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(goals, position()):
    end_turn()

move_towards( closest(goals) )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# v1: v0 plus a Vesper/Heart/Marcella/Vendetta/Ryth draft chain, safer tribute altars
# (away from monoliths), retreat when hurt and in danger, and backing off from
# unfavourable local fights.

# ---- tunable constants (as literals) ----
# fight only when local_strength(4) >= 0.7 or health is high
# retreat to spawn when in_danger() and health < 35%
# recall at 20% health, or at 50% when carrying gems

def safe_altars():
    return minus( minus( altars(), locked_altars() ), ring( monolith_tiles(), 5 ) )

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat: recall at 20% health, or at 50% when carrying gems
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    recall()
    end_turn()

# badly hurt and under threat: walk back toward spawn rather than trade
if not at_spawn and health() < 0.35 * max_health() and in_danger():
    move_towards( closest( spawn_region(ally()) ) )
    end_turn()

let enemy = first( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    # outnumbered and hurt: step away instead of trading
    if local_strength(4) < 0.7 and health() < 0.6 * max_health():
        move_away_from( unit_position(enemy) )
        end_turn()
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

if gems() > 0:
    let open_altars = minus( altars(), locked_altars() )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # prefer altars outside monolith reach; fall back to any open altar
    if exists( closest( ring( safe_altars(), 1 ) ) ):
        move_towards( closest( ring( safe_altars(), 1 ) ) )
        end_turn()
    move_towards( closest( ring( open_altars, 1 ) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(goals, position()):
    end_turn()

move_towards( closest(goals) )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
